-- DROP SCHEMA agi_evolution;

CREATE SCHEMA agi_evolution AUTHORIZATION postgres;




-- agi_evolution.causal_links definition

-- Drop table

-- DROP TABLE agi_evolution.causal_links;

CREATE TABLE agi_evolution.causal_links (
	id uuid DEFAULT gen_random_uuid() NOT NULL,
	source_id uuid NULL,
	target_id uuid NULL,
	weight float8 DEFAULT 1.0 NULL,
	delay float8 DEFAULT 0.0 NULL,
	probability float8 DEFAULT 0.5 NULL,
	usage_count int4 DEFAULT 0 NULL,
	success_count int4 DEFAULT 0 NULL,
	metadata jsonb DEFAULT '{}'::jsonb NULL,
	created_at timestamp DEFAULT CURRENT_TIMESTAMP NULL,
	updated_at timestamp DEFAULT CURRENT_TIMESTAMP NULL,
	CONSTRAINT causal_links_pkey PRIMARY KEY (id)
);
CREATE INDEX idx_causal_links_source ON agi_evolution.causal_links USING btree (source_id);
CREATE INDEX idx_causal_links_target ON agi_evolution.causal_links USING btree (target_id);


-- agi_evolution.causal_links foreign keys

ALTER TABLE agi_evolution.causal_links ADD CONSTRAINT causal_links_source_id_fkey FOREIGN KEY (source_id) REFERENCES agi_evolution.emotion_events(id);
ALTER TABLE agi_evolution.causal_links ADD CONSTRAINT causal_links_target_id_fkey FOREIGN KEY (target_id) REFERENCES agi_evolution.emotion_events(id);




