	 ('8a7543aa-e916-4c49-bea0-5e7882a6529d'::uuid,'OPEN SECTION WIND TUNNELS','SYSTEM','{"{\"название\": \"OPEN SECTION WIND TUNNELS\", \"описание\": \"Tunnels without full enclosure, leading to instability due to vortex shedding from jet edges\"}"}','Tunnels without full enclosure, leading to instability due to vortex shedding from jet edges','{}','{}','{"frequency": 2, "text_unit_ids": ["61646302e3bc960c352c6408cdc69191dab988abf38ec4bf7f2e4174aba91d86396e3e37ae38ca304afb1a34043af419361016661c11be52244507e7a8027a39", "61646302e3bc960c352c6408cdc69191dab988abf38ec4bf7f2e4174aba91d86396e3e37ae38ca304afb1a34043af419361016661c11be52244507e7a8027a39"]}','2026-07-17 13:19:24.183818','2026-07-17 13:19:24.183818','history_development_aeronautics'),
	 ('b876255d-3b96-4906-87ca-2b16948e33ce'::uuid,'VARIABLE DENSITY TUNNELS','SYSTEM','{"{\"название\": \"VARIABLE DENSITY TUNNELS\", \"описание\": \"Developed after World War I to overcome Reynolds number problems by creating more realistic test env\"}"}','Developed after World War I to overcome Reynolds number problems by creating more realistic test environments','{}','{}','{"frequency": 2, "text_unit_ids": ["61646302e3bc960c352c6408cdc69191dab988abf38ec4bf7f2e4174aba91d86396e3e37ae38ca304afb1a34043af419361016661c11be52244507e7a8027a39", "61646302e3bc960c352c6408cdc69191dab988abf38ec4bf7f2e4174aba91d86396e3e37ae38ca304afb1a34043af419361016661c11be52244507e7a8027a39"]}','2026-07-17 13:19:24.183818','2026-07-17 13:19:24.183818','history_development_aeronautics'),
