	 ('d201bd41-8b71-4019-a1c6-89f813c0407f'::uuid,'DIAMETER SQUARE DEPENDENCE','SYSTEM','{"{\"название\": \"DIAMETER SQUARE DEPENDENCE\", \"описание\": \"(\\\\(d^2\\\\)), another relationship seen in tests, indicating that some resistances might depend on the \"}"}','(\(d^2\)), another relationship seen in tests, indicating that some resistances might depend on the square of the diameter','{}','{}','{"frequency": 1, "text_unit_ids": ["8e8b5bf24dddb1ddb50b7cbf2d3c92c98694db8e547ae1917342574e7e171cb95e09a476096026b49868f4048da326a354b623333e0ac1b3a5e0a358ea00009f"]}','2026-07-17 13:19:24.183818','2026-07-17 13:19:24.183818','history_development_aeronautics');
