	 ('241deb60-0455-4514-a7c0-7380ea62449a'::uuid,'GASEOUS FLOW MECHANICS','SYSTEM','{"{\"название\": \"GASEOUS FLOW MECHANICS\", \"описание\": \"Study of fluid dynamics, especially gases, crucial for understanding aircraft design and performance\"}"}','Study of fluid dynamics, especially gases, crucial for understanding aircraft design and performance)("relationship"','{}','{}','{"frequency": 2, "text_unit_ids": ["a779458276374a63d6d046677182afa54f82096d7fed98598f3c9892f3ddfcdc556726406f2c8e10c2ecdc5eecba1fee902de22803c3813dde63bc3545bc66ae", "a779458276374a63d6d046677182afa54f82096d7fed98598f3c9892f3ddfcdc556726406f2c8e10c2ecdc5eecba1fee902de22803c3813dde63bc3545bc66ae"]}','2026-07-17 16:18:55.489892','2026-07-17 16:18:55.489892','aerodynamics_v1'),
	 ('b0e2ce86-4d72-4cd4-bcda-90716ad83cd2'::uuid,'THRUST','FORCE','{"{\"название\": \"THRUST\", \"описание\": \"Thrust is generated by the engine and acts against drag\"}"}','Thrust is generated by the engine and acts against drag','{}','{}','{"frequency": 1, "text_unit_ids": ["a9ae9046c84bd485f66f44763948025a4066f10073bee095a4c15c4665d9db3e9ee4c83182db236d7659a96a72f09b4262666709a85154db90a6633d796a8eab"]}','2026-07-17 16:18:55.489892','2026-07-17 16:18:55.489892','aerodynamics_v1'),
	 ('d5b1fda8-9fcd-41ae-ac11-79a381356edf'::uuid,'DRAG','FORCE','{"{\"название\": \"DRAG\", \"описание\": \"Drag opposes thrust and is caused by air resistance\"}"}','Drag opposes thrust and is caused by air resistance','{}','{}','{"frequency": 1, "text_unit_ids": ["a9ae9046c84bd485f66f44763948025a4066f10073bee095a4c15c4665d9db3e9ee4c83182db236d7659a96a72f09b4262666709a85154db90a6633d796a8eab"]}','2026-07-17 16:18:55.489892','2026-07-17 16:18:55.489892','aerodynamics_v1'),
	 ('e68bcac3-2fba-4371-9d20-c213edac9765'::uuid,'WEIGHT','FORCE','{"{\"название\": \"WEIGHT\", \"описание\": \"Weight acts downwards due to gravity, balancing the forces for stable flight\"}"}','Weight acts downwards due to gravity, balancing the forces for stable flight','{}','{}','{"frequency": 1, "text_unit_ids": ["a9ae9046c84bd485f66f44763948025a4066f10073bee095a4c15c4665d9db3e9ee4c83182db236d7659a96a72f09b4262666709a85154db90a6633d796a8eab"]}','2026-07-17 16:18:55.489892','2026-07-17 16:18:55.489892','aerodynamics_v1'),
	 ('385d2a72-4951-471f-be97-2833b9f52c20'::uuid,'FLAG FLUTTERING IN THE WIND','PHENOMENA','{}','A phenomenon where a flag oscillates due to wind forces, indicating the need for considering deformations','{}','{}','{"frequency": 2, "text_unit_ids": ["16d392b029485723ce65bbac01611d8cea0ac0a495dfcec849dfe0fb70a7ecd2ca1be47fb6b9a17cde8832f82f25c06409dae658149352efbf16e7cc4637347b", "16d392b029485723ce65bbac01611d8cea0ac0a495dfcec849dfe0fb70a7ecd2ca1be47fb6b9a17cde8832f82f25c06409dae658149352efbf16e7cc4637347b"]}','2026-07-17 16:18:55.489892','2026-07-17 16:18:55.489892','aerodynamics_v1');
