	 ('6a0b0714-5707-448c-9d03-5cf1b41d362a'::uuid,'IDEAL COMPRESSIBLE FLUID (GAS) MODEL','MODEL','{"{\"название\": \"IDEAL COMPRESSIBLE FLUID (GAS) MODEL\", \"описание\": \"Used widely in acoustics, this model assumes small Mach numbers and simplifies the analysis of sound\"}"}','Used widely in acoustics, this model assumes small Mach numbers and simplifies the analysis of sound wave generation and propagation.','{}','{}','{"frequency": 2, "text_unit_ids": ["7bab4e0b9bf564415098605230a0b8c9801762a344b1305f6767edd6b3d9c9e7d69c62df8d4aa634a80ec96f8417c044943b33570af019c7be0aee94a675a2da", "7bab4e0b9bf564415098605230a0b8c9801762a344b1305f6767edd6b3d9c9e7d69c62df8d4aa634a80ec96f8417c044943b33570af019c7be0aee94a675a2da"]}','2026-07-17 16:18:55.489892','2026-07-17 16:18:55.489892','aerodynamics_v1'),
	 ('5d913418-d328-4629-8321-65c56e959c15'::uuid,'VISCOUS COMPRESSIBLE GAS MODEL','MODEL','{"{\"название\": \"VISCOUS COMPRESSIBLE GAS MODEL\", \"описание\": \"This comprehensive model most accurately describes aerodynamic processes but introduces complex math\"}"}','This comprehensive model most accurately describes aerodynamic processes but introduces complex mathematical problems due to compressibility and viscosity considerations.','{}','{}','{"frequency": 2, "text_unit_ids": ["7bab4e0b9bf564415098605230a0b8c9801762a344b1305f6767edd6b3d9c9e7d69c62df8d4aa634a80ec96f8417c044943b33570af019c7be0aee94a675a2da", "7bab4e0b9bf564415098605230a0b8c9801762a344b1305f6767edd6b3d9c9e7d69c62df8d4aa634a80ec96f8417c044943b33570af019c7be0aee94a675a2da"]}','2026-07-17 16:18:55.489892','2026-07-17 16:18:55.489892','aerodynamics_v1'),
	 ('593724cd-3f23-424f-a6ed-b0b0a8a34ffc'::uuid,'FLOW PROCESS','SYSTEM','{"{\"название\": \"FLOW PROCESS\", \"описание\": \"Refers to the movement of fluid or gas and its characteristics, which are described by various model\"}"}','Refers to the movement of fluid or gas and its characteristics, which are described by various models used in aerodynamics.','{}','{}','{"frequency": 2, "text_unit_ids": ["7bab4e0b9bf564415098605230a0b8c9801762a344b1305f6767edd6b3d9c9e7d69c62df8d4aa634a80ec96f8417c044943b33570af019c7be0aee94a675a2da", "7bab4e0b9bf564415098605230a0b8c9801762a344b1305f6767edd6b3d9c9e7d69c62df8d4aa634a80ec96f8417c044943b33570af019c7be0aee94a675a2da"]}','2026-07-17 16:18:55.489892','2026-07-17 16:18:55.489892','aerodynamics_v1'),
	 ('4cbb1c53-f235-4fe0-8cbd-a955c37f9cff'::uuid,'FLOW CLASSIFICATION','SYSTEM','{"{\"название\": \"FLOW CLASSIFICATION\", \"описание\": \"The classification of flows in aerodynamics, which is essential based on criteria such as Mach numbe\"}"}','The classification of flows in aerodynamics, which is essential based on criteria such as Mach number and flow structure like laminar or turbulent characteristics.','{}','{}','{"frequency": 2, "text_unit_ids": ["7bab4e0b9bf564415098605230a0b8c9801762a344b1305f6767edd6b3d9c9e7d69c62df8d4aa634a80ec96f8417c044943b33570af019c7be0aee94a675a2da", "7bab4e0b9bf564415098605230a0b8c9801762a344b1305f6767edd6b3d9c9e7d69c62df8d4aa634a80ec96f8417c044943b33570af019c7be0aee94a675a2da"]}','2026-07-17 16:18:55.489892','2026-07-17 16:18:55.489892','aerodynamics_v1'),
